'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useState } from 'react';

import { PlusIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';

import { ColumnLabels } from './column-labels';
import { TASKS, type PriorityId, type StatusId, type Task } from './data';
import { FilteredEmpty, ScopeEmpty } from './empty-list';
import { FilterMenu } from './filter-menu';
import { fadePresence } from './motion-parts';
import { ScopeSwitch } from './scope-switch';
import { SearchField } from './search-field';
import { TaskGroup } from './task-group';
import {
  countLabel,
  EMPTY_FILTERS,
  groupsOf,
  isFiltering,
  isInScope,
  matchesFilters,
  matchesSearch,
  nextTaskNumberOf,
  patchedTask,
  scopeCountsOf,
  toggledFilters,
  toggledIds,
  type FilterKey,
  type Filters,
  type Scope,
} from './task-model';
import { useDelayedPlacement } from './use-delayed-placement';

const NEW_TASK_STATUS: StatusId = 'todo';

function headerMetaOf(tasks: Task[]) {
  const total = countLabel(tasks.length, 'task', 'tasks');
  const trackedCount = tasks.filter((task) => task.trackedById).length;
  if (trackedCount === 0) {
    return total;
  }
  return `${total} · ${trackedCount} tracked now`;
}

export default function TaskLists01() {
  const [tasks, setTasks] = useState<Task[]>(TASKS);
  const [scope, setScope] = useState<Scope>('active');
  const [query, setQuery] = useState('');
  const [filters, setFilters] = useState<Filters>(EMPTY_FILTERS);
  const [collapsed, setCollapsed] = useState<StatusId[]>([]);
  const [draftStatus, setDraftStatus] = useState<StatusId | null>(null);
  const placement = useDelayedPlacement();

  const matchingTasks = tasks.filter(
    (task) => matchesSearch(task, query) && matchesFilters(task, filters)
  );
  const scopeCounts = scopeCountsOf(matchingTasks);
  const allScopeCounts = scopeCountsOf(tasks);
  const scopeTasks = tasks.filter((task) => isInScope(task.status, scope));
  const visibleTasks = matchingTasks.filter((task) =>
    isInScope(placement.placementOf(task), scope)
  );
  const groups = groupsOf(
    visibleTasks,
    scope,
    placement.placementOf,
    draftStatus
  );
  const hasGroups = groups.length > 0;
  const isFiltered = isFiltering(query, filters);
  const showsFilteredEmpty = !hasGroups && isFiltered;
  const showsScopeEmpty = !hasGroups && !isFiltered;

  function updateTask(taskId: string, patch: Partial<Task>) {
    setTasks((current) =>
      current.map((task) => patchedTask(task, taskId, patch))
    );
  }

  function changeStatus(taskId: string, status: StatusId) {
    const task = tasks.find((item) => item.id === taskId);
    if (!task) {
      return;
    }
    if (task.status === status) {
      return;
    }
    placement.hold(taskId, task.status);
    updateTask(taskId, { status });
  }

  function changePriority(taskId: string, priority: PriorityId) {
    updateTask(taskId, { priority });
  }

  function changeAssignees(taskId: string, assigneeIds: string[]) {
    updateTask(taskId, { assigneeIds });
  }

  function toggleCollapsed(status: StatusId) {
    const isCollapsed = collapsed.includes(status);
    setCollapsed(toggledIds(collapsed, status, !isCollapsed));
  }

  function startDraft(status: StatusId) {
    const isHiddenByScope = !isInScope(status, scope);
    if (isHiddenByScope) {
      setScope('active');
    }
    setCollapsed((current) => current.filter((item) => item !== status));
    setDraftStatus(status);
  }

  function createTask(status: StatusId, title: string) {
    const number = nextTaskNumberOf(tasks);
    const task: Task = {
      id: `mos-${number}`,
      number,
      title,
      type: 'task',
      status,
      priority: 'none',
      labelIds: [],
      assigneeIds: [],
    };
    setTasks((current) => [task, ...current]);
    setDraftStatus(null);
  }

  function toggleFilter(key: FilterKey, value: string, isIncluded: boolean) {
    setFilters((current) => toggledFilters(current, key, value, isIncluded));
  }

  function clearFilters() {
    setQuery('');
    setFilters(EMPTY_FILTERS);
  }

  return (
    <div className='bg-background text-foreground @container flex h-svh min-h-[28rem] flex-col'>
      <header className='flex flex-col gap-3 px-3 pt-4 pb-3 sm:px-5'>
        <div className='flex items-center justify-between gap-3'>
          <div className='min-w-0'>
            <h1 className='truncate text-sm font-semibold'>Tasks</h1>
            <p className='text-muted-foreground text-xs'>
              {headerMetaOf(tasks)}
            </p>
          </div>
          <Button onClick={() => startDraft(NEW_TASK_STATUS)}>
            <PlusIcon />
            New task
          </Button>
        </div>
        <div className='flex flex-wrap items-center gap-2'>
          <ScopeSwitch scope={scope} counts={scopeCounts} onChange={setScope} />
          <div className='flex w-full items-center gap-2 @xl:ml-auto @xl:w-auto'>
            <SearchField
              value={query}
              onChange={setQuery}
              placeholder='Search tasks'
              className='min-w-0 flex-1 @xl:w-56 @xl:flex-none'
            />
            <FilterMenu
              tasks={scopeTasks}
              filters={filters}
              onToggle={toggleFilter}
              onClear={clearFilters}
            />
          </div>
        </div>
      </header>
      <div className='relative min-h-0 flex-1 overflow-y-auto'>
        <AnimatePresence mode='popLayout' initial={false}>
          {hasGroups && (
            <motion.div
              key='list'
              role='table'
              aria-label='Tasks'
              {...fadePresence()}
              className='pb-6'
            >
              <ColumnLabels />
              <AnimatePresence initial={false}>
                {groups.map((group) => (
                  <TaskGroup
                    key={group.status}
                    status={group.status}
                    tasks={group.tasks}
                    isCollapsed={collapsed.includes(group.status)}
                    isDrafting={draftStatus === group.status}
                    onToggleCollapsed={toggleCollapsed}
                    onStartDraft={startDraft}
                    onCreate={createTask}
                    onCancelDraft={() => setDraftStatus(null)}
                    onStatusChange={changeStatus}
                    onPriorityChange={changePriority}
                    onAssigneesChange={changeAssignees}
                  />
                ))}
              </AnimatePresence>
            </motion.div>
          )}
          {showsFilteredEmpty && (
            <motion.div key='filtered' {...fadePresence()}>
              <FilteredEmpty
                scope={scope}
                query={query}
                filters={filters}
                scopeTotal={allScopeCounts[scope]}
                onClear={clearFilters}
              />
            </motion.div>
          )}
          {showsScopeEmpty && (
            <motion.div key='empty' {...fadePresence()}>
              <ScopeEmpty
                scope={scope}
                onNewTask={() => startDraft(NEW_TASK_STATUS)}
                onShowActive={() => setScope('active')}
              />
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
}

'use client';

import { motion, useReducedMotion } from 'motion/react';
import { useEffect, useRef, useState } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';
import { Kbd } from '@/registry/ndeko/ui/kbd';

import type { StatusId } from './data';
import { heightPresenceOf } from './motion-parts';
import { IssueTypeGem, StatusGlyph } from './task-glyphs';
import {
  DRAFT_TITLE_CELL,
  ID_CELL,
  PRIORITY_CELL,
  ROW_CLASS,
  TASK_GRID,
} from './task-grid';
import { statusOf } from './task-model';

type DraftRowProps = {
  status: StatusId;
  onCreate: (title: string) => void;
  onCancel: () => void;
};

export function DraftRow({ status, onCreate, onCancel }: DraftRowProps) {
  const shouldReduceMotion = useReducedMotion();
  const presence = heightPresenceOf(shouldReduceMotion);
  const inputRef = useRef<HTMLInputElement>(null);
  const [title, setTitle] = useState('');
  const statusName = statusOf(status).name;

  useEffect(() => {
    inputRef.current?.focus();
  }, []);

  function submit() {
    const trimmed = title.trim();
    if (!trimmed) {
      onCancel();
      return;
    }
    onCreate(trimmed);
  }

  function handleKeyDown(event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key === 'Enter') {
      event.preventDefault();
      submit();
      return;
    }
    if (event.key === 'Escape') {
      event.preventDefault();
      onCancel();
    }
  }

  function handleBlur() {
    const isEmpty = title.trim().length === 0;
    if (isEmpty) {
      onCancel();
    }
  }

  return (
    <motion.div
      role='row'
      {...presence}
      className={cn(TASK_GRID, ROW_CLASS, 'bg-primary/[0.04]')}
    >
      <div role='cell' className={PRIORITY_CELL} />
      <div role='cell' className={cn(ID_CELL, 'text-muted-foreground text-xs')}>
        New
      </div>
      <div role='cell' className='flex size-7 items-center justify-center'>
        <StatusGlyph status={status} />
      </div>
      <div
        role='cell'
        className={cn('flex min-w-0 items-center gap-2', DRAFT_TITLE_CELL)}
      >
        <IssueTypeGem type='task' />
        <input
          ref={inputRef}
          value={title}
          onChange={(event) => setTitle(event.target.value)}
          onKeyDown={handleKeyDown}
          onBlur={handleBlur}
          aria-label={`New task in ${statusName}`}
          placeholder='Task title'
          className='placeholder:text-muted-foreground/75 h-7 min-w-0 flex-1 bg-transparent text-base outline-none md:text-[13px]'
        />
        <Kbd className='hidden sm:inline-flex'>Enter</Kbd>
      </div>
    </motion.div>
  );
}

import {
  CircleCheckIcon,
  PlusIcon,
  SearchIcon,
  XIcon,
} from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';

import {
  activeFilterCountOf,
  countLabel,
  scopeOf,
  type Filters,
  type Scope,
} from './task-model';

type EmptyFrameProps = {
  icon: React.ReactNode;
  title: string;
  line: string;
  action: React.ReactNode;
};

function EmptyFrame({ icon, title, line, action }: EmptyFrameProps) {
  return (
    <div className='flex flex-col items-center px-6 py-16 text-center'>
      <span className='keycap-3d text-muted-foreground flex size-9 items-center justify-center rounded-lg'>
        {icon}
      </span>
      <p className='mt-4 text-sm font-medium'>{title}</p>
      <p className='text-muted-foreground mt-1 max-w-sm text-[13px] text-balance'>
        {line}
      </p>
      <div className='mt-4'>{action}</div>
    </div>
  );
}

function criteriaOf(query: string, filters: Filters) {
  const trimmed = query.trim();
  const filterCount = activeFilterCountOf(filters);
  const filterPhrase = countLabel(filterCount, 'filter', 'filters');
  const hasFilters = filterCount > 0;
  if (!trimmed) {
    return filterPhrase;
  }
  if (!hasFilters) {
    return `“${trimmed}”`;
  }
  return `“${trimmed}” with ${filterPhrase}`;
}

function reachOf(scope: Scope, scopeTotal: number) {
  const option = scopeOf(scope);
  if (scopeTotal === 0) {
    return `and there are no ${option.plural} yet`;
  }
  if (scopeTotal === 1) {
    return `clear them to see the one ${option.singular}`;
  }
  return `clear them to see all ${scopeTotal} ${option.plural}`;
}

function filteredLineOf(
  scope: Scope,
  query: string,
  filters: Filters,
  scopeTotal: number
) {
  const option = scopeOf(scope);
  const criteria = criteriaOf(query, filters);
  const reach = reachOf(scope, scopeTotal);
  return `No ${option.singular} matches ${criteria}, ${reach}`;
}

type FilteredEmptyProps = {
  scope: Scope;
  query: string;
  filters: Filters;
  scopeTotal: number;
  onClear: () => void;
};

export function FilteredEmpty({
  scope,
  query,
  filters,
  scopeTotal,
  onClear,
}: FilteredEmptyProps) {
  return (
    <EmptyFrame
      icon={<SearchIcon />}
      title='No tasks match'
      line={filteredLineOf(scope, query, filters, scopeTotal)}
      action={
        <Button variant='outline' onClick={onClear}>
          <XIcon />
          Clear filters
        </Button>
      }
    />
  );
}

type ScopeEmptyProps = {
  scope: Scope;
  onNewTask: () => void;
  onShowActive: () => void;
};

export function ScopeEmpty({
  scope,
  onNewTask,
  onShowActive,
}: ScopeEmptyProps) {
  if (scope === 'done') {
    return (
      <EmptyFrame
        icon={<CircleCheckIcon />}
        title='No finished tasks'
        line='Tasks moved to Done appear here'
        action={
          <Button variant='outline' onClick={onShowActive}>
            Show active tasks
          </Button>
        }
      />
    );
  }
  return (
    <EmptyFrame
      icon={<CircleCheckIcon />}
      title='No active tasks'
      line='All tasks are done, add one to plan what comes next'
      action={
        <Button onClick={onNewTask}>
          <PlusIcon />
          New task
        </Button>
      }
    />
  );
}

'use client';

import {
  CircleDashedIcon,
  HashIcon,
  LayersIcon,
  ListFilterIcon,
  UserIcon,
  UserRoundIcon,
  XIcon,
} from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuTrigger,
} from '@/registry/ndeko/ui/dropdown-menu';
import { Kbd } from '@/registry/ndeko/ui/kbd';

import {
  ISSUE_TYPES,
  LABELS,
  PEOPLE,
  PRIORITIES,
  STATUSES,
  type Task,
} from './data';
import { RollingCount } from './motion-parts';
import {
  IssueTypeGem,
  PersonAvatar,
  PriorityGlyph,
  StatusGlyph,
} from './task-glyphs';
import {
  activeFilterCountOf,
  assigneeValuesOf,
  NO_ASSIGNEE,
  type FilterKey,
  type Filters,
} from './task-model';

type FilterOption = {
  value: string;
  label: string;
  glyph: React.ReactNode;
  count: number;
};

type FilterProperty = {
  key: FilterKey;
  label: string;
  glyph: React.ReactNode;
  options: FilterOption[];
};

function countBy(tasks: Task[], valuesOf: (task: Task) => string[]) {
  const counts = new Map<string, number>();
  for (const task of tasks) {
    for (const value of valuesOf(task)) {
      const current = counts.get(value) ?? 0;
      counts.set(value, current + 1);
    }
  }
  return counts;
}

function LabelDot({ color }: { color: string }) {
  const dotStyle = { backgroundColor: color } as React.CSSProperties;
  return (
    <span
      aria-hidden='true'
      style={dotStyle}
      className='mx-1 size-2 shrink-0 rounded-full'
    />
  );
}

function filterPropertiesOf(tasks: Task[]): FilterProperty[] {
  const statusCounts = countBy(tasks, (task) => [task.status]);
  const priorityCounts = countBy(tasks, (task) => [task.priority]);
  const assigneeCounts = countBy(tasks, assigneeValuesOf);
  const labelCounts = countBy(tasks, (task) => task.labelIds);
  const typeCounts = countBy(tasks, (task) => [task.type]);

  const assigneeOptions: FilterOption[] = PEOPLE.map((person) => ({
    value: person.id,
    label: person.name,
    glyph: <PersonAvatar person={person} className='size-4 text-[8px]' />,
    count: assigneeCounts.get(person.id) ?? 0,
  }));
  assigneeOptions.push({
    value: NO_ASSIGNEE,
    label: 'No assignee',
    glyph: <UserRoundIcon />,
    count: assigneeCounts.get(NO_ASSIGNEE) ?? 0,
  });

  return [
    {
      key: 'status',
      label: 'Status',
      glyph: <CircleDashedIcon />,
      options: STATUSES.map((status) => ({
        value: status.id,
        label: status.name,
        glyph: <StatusGlyph status={status.id} />,
        count: statusCounts.get(status.id) ?? 0,
      })),
    },
    {
      key: 'priority',
      label: 'Priority',
      glyph: (
        <PriorityGlyph priority='high' className='text-muted-foreground' />
      ),
      options: PRIORITIES.map((priority) => ({
        value: priority.id,
        label: priority.name,
        glyph: <PriorityGlyph priority={priority.id} />,
        count: priorityCounts.get(priority.id) ?? 0,
      })),
    },
    {
      key: 'assignee',
      label: 'Assignee',
      glyph: <UserIcon />,
      options: assigneeOptions,
    },
    {
      key: 'label',
      label: 'Label',
      glyph: <HashIcon />,
      options: LABELS.map((label) => ({
        value: label.id,
        label: label.name,
        glyph: <LabelDot color={label.color} />,
        count: labelCounts.get(label.id) ?? 0,
      })),
    },
    {
      key: 'type',
      label: 'Type',
      glyph: <LayersIcon />,
      options: ISSUE_TYPES.map((type) => ({
        value: type.id,
        label: type.name,
        glyph: <IssueTypeGem type={type.id} />,
        count: typeCounts.get(type.id) ?? 0,
      })),
    },
  ];
}

type FilterMenuProps = {
  tasks: Task[];
  filters: Filters;
  onToggle: (key: FilterKey, value: string, isIncluded: boolean) => void;
  onClear: () => void;
};

export function FilterMenu({
  tasks,
  filters,
  onToggle,
  onClear,
}: FilterMenuProps) {
  const properties = filterPropertiesOf(tasks);
  const activeCount = activeFilterCountOf(filters);
  const hasActive = activeCount > 0;

  return (
    <DropdownMenu>
      <DropdownMenuTrigger render={<Button variant='outline' />}>
        <ListFilterIcon />
        Filter
        {hasActive && (
          <span className='bg-primary/10 text-primary-ink -me-1.5 inline-flex h-5 min-w-5 items-center justify-center rounded-full px-1.5 text-xs'>
            <RollingCount value={activeCount} />
            <span className='sr-only'> active</span>
          </span>
        )}
      </DropdownMenuTrigger>
      <DropdownMenuContent align='end' className='w-52'>
        {properties.map((property) => {
          const selected = filters[property.key];
          const selectedCount = selected.length;
          const hasSelection = selectedCount > 0;
          return (
            <DropdownMenuSub key={property.key}>
              <DropdownMenuSubTrigger>
                {property.glyph}
                <span className='flex-1'>{property.label}</span>
                {hasSelection && <Kbd>{selectedCount}</Kbd>}
              </DropdownMenuSubTrigger>
              <DropdownMenuSubContent className='w-56'>
                {property.options.map((option) => (
                  <DropdownMenuCheckboxItem
                    key={option.value}
                    checked={selected.includes(option.value)}
                    onCheckedChange={(checked) =>
                      onToggle(property.key, option.value, checked)
                    }
                  >
                    {option.glyph}
                    <span className='min-w-0 flex-1 truncate'>
                      {option.label}
                    </span>
                    <span className='text-muted-foreground text-xs tabular-nums'>
                      {option.count}
                    </span>
                  </DropdownMenuCheckboxItem>
                ))}
              </DropdownMenuSubContent>
            </DropdownMenuSub>
          );
        })}
        <DropdownMenuSeparator />
        <DropdownMenuItem disabled={!hasActive} onClick={onClear}>
          <XIcon />
          Clear filters
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  useReducedMotion,
  type MotionProps,
  type Transition,
  type Variants,
} from 'motion/react';
import { useState } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';

const EASE_OUT_STRONG: [number, number, number, number] = [0.23, 1, 0.32, 1];

const ENTER: Transition = { duration: 0.2, ease: EASE_OUT_STRONG };

const EXIT: Transition = { duration: 0.15, ease: EASE_OUT_STRONG };

type PresenceProps = Pick<
  MotionProps,
  'initial' | 'animate' | 'exit' | 'transition'
>;

const HEIGHT_PRESENCE: PresenceProps = {
  initial: { height: 0, opacity: 0 },
  animate: { height: 'auto', opacity: 1 },
  exit: { height: 0, opacity: 0, transition: EXIT },
  transition: ENTER,
};

const FADE_PRESENCE: PresenceProps = {
  initial: { opacity: 0 },
  animate: { opacity: 1 },
  exit: { opacity: 0, transition: EXIT },
  transition: ENTER,
};

export function heightPresenceOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_PRESENCE;
  }
  return HEIGHT_PRESENCE;
}

export function fadePresence() {
  return FADE_PRESENCE;
}

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: EASE_OUT_STRONG };

const SWAP_VARIANTS: Variants = {
  hidden: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  shown: { opacity: 1, scale: 1, filter: 'blur(0px)' },
};

const FADE_VARIANTS: Variants = {
  hidden: { opacity: 0 },
  shown: { opacity: 1 },
};

function swapVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SWAP_VARIANTS;
}

type SwapProps = {
  swapKey: string;
  children: React.ReactNode;
  className?: string;
};

export function Swap({ swapKey, children, className }: SwapProps) {
  const shouldReduceMotion = useReducedMotion();
  const variants = swapVariantsOf(shouldReduceMotion);

  return (
    <span className={cn('relative inline-flex', className)}>
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={swapKey}
          variants={variants}
          initial='hidden'
          animate='shown'
          exit='hidden'
          transition={SWAP_TRANSITION}
          className='inline-flex'
        >
          {children}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

const COUNT_SLIDE = 8;

const COUNT_TRANSITION: Transition = { duration: 0.18, ease: EASE_OUT_STRONG };

const COUNT_VARIANTS: Variants = {
  enter: (offset: number) => ({ y: offset, opacity: 0 }),
  center: { y: 0, opacity: 1 },
  leave: (offset: number) => ({ y: -offset, opacity: 0 }),
};

function directionOf(previous: number, next: number) {
  if (next < previous) {
    return -1;
  }
  return 1;
}

function offsetOf(direction: number, shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return 0;
  }
  return direction * COUNT_SLIDE;
}

export function RollingCount({
  value,
  className,
}: {
  value: number;
  className?: string;
}) {
  const shouldReduceMotion = useReducedMotion();
  const [previous, setPrevious] = useState(value);
  const [direction, setDirection] = useState(1);

  if (previous !== value) {
    setDirection(directionOf(previous, value));
    setPrevious(value);
  }

  const offset = offsetOf(direction, shouldReduceMotion);

  return (
    <span
      className={cn(
        'relative inline-flex overflow-hidden tabular-nums',
        className
      )}
    >
      <AnimatePresence mode='popLayout' initial={false} custom={offset}>
        <motion.span
          key={value}
          custom={offset}
          variants={COUNT_VARIANTS}
          initial='enter'
          animate='center'
          exit='leave'
          transition={COUNT_TRANSITION}
          className='inline-block'
        >
          {value}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

'use client';

import { UserRoundPlusIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuTrigger,
} from '@/registry/ndeko/ui/dropdown-menu';

import {
  PEOPLE,
  PRIORITIES,
  STATUSES,
