export function StatusPicker({
  status,
  onChange,
}: {
  status: StatusId;
  onChange: (status: StatusId) => void;
}) {
  const meta = statusOf(status);

  function pick(value: unknown) {
    if (isStatusId(value)) {
      onChange(value);
    }
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        aria-label={`Status: ${meta.name}. Change status`}
        className={CELL_TRIGGER}
      >
        <Swap swapKey={status}>
          <StatusGlyph status={status} />
        </Swap>
      </DropdownMenuTrigger>
      <DropdownMenuContent className='w-48'>
        <DropdownMenuRadioGroup value={status} onValueChange={pick}>
          {STATUSES.map((option) => (
            <DropdownMenuRadioItem
              key={option.id}
              value={option.id}
              closeOnClick
            >
              <StatusGlyph status={option.id} />
              {option.name}
            </DropdownMenuRadioItem>
          ))}
        </DropdownMenuRadioGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

