  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        aria-label={assigneeLabelOf(names)}
        className={cn(CELL_TRIGGER, 'w-auto min-w-7 px-1')}
      >
        {hasAssignees && <PeopleStack people={assignees} />}
        {!hasAssignees && (
          <UserRoundPlusIcon
            className={cn('text-muted-foreground size-4', HOVER_ONLY)}
          />
        )}
