const PRIORITY_BARS = [
  { x: 1.5, height: 4 },
  { x: 5.75, height: 7 },
  { x: 10, height: 10 },
];

const FILLED_BAR_COUNT: Record<PriorityId, number> = {
  urgent: 3,
  high: 3,
  medium: 2,
  low: 1,
  none: 0,
};

function barOpacityOf(index: number, filledCount: number) {
  if (index < filledCount) {
    return 0.75;
  }
  return 0.2;
}

function priorityShapeOf(priority: PriorityId) {
  if (priority === 'urgent') {
    return (
      <g style={{ color: 'var(--destructive)' }}>
        <rect
          x='1'
          y='1'
          width='12'
          height='12'
          rx='3.5'
          fill='currentColor'
          fillOpacity='0.16'
        />
        <rect
          x='6.25'
          y='3.5'
          width='1.5'
          height='4.75'
          rx='0.75'
          fill='currentColor'
        />
        <circle cx='7' cy='10.1' r='0.95' fill='currentColor' />
      </g>
    );
  }
  if (priority === 'none') {
    return (
      <g fill='currentColor' fillOpacity='0.45'>
        {PRIORITY_BARS.map((bar) => (
          <rect
            key={bar.x}
            x={bar.x}
            y='6.25'
            width='2.5'
            height='1.5'
            rx='0.75'
          />
        ))}
      </g>
    );
  }
  const filledCount = FILLED_BAR_COUNT[priority];
  return (
    <g fill='currentColor'>
      {PRIORITY_BARS.map((bar, index) => (
        <rect
          key={bar.x}
          x={bar.x}
          y={12 - bar.height}
          width='2.5'
          height={bar.height}
          rx='0.75'
          fillOpacity={barOpacityOf(index, filledCount)}
        />
      ))}
    </g>
  );
}

