};

function byId<Item extends { id: string }>(items: Item[], id: string): Item {
  const found = items.find((item) => item.id === id);
  if (found) {
    return found;
  }
  return items[0];
}

export function statusOf(id: StatusId) {
  return byId(STATUSES, id);
}

export function priorityOf(id: PriorityId) {
  return byId(PRIORITIES, id);
}

export function issueTypeOf(id: IssueTypeId) {
  return byId(ISSUE_TYPES, id);
}

export function peopleOf(ids: string[]) {
  return PEOPLE.filter((person) => ids.includes(person.id));
}

export function labelsOf(ids: string[]) {
  return LABELS.filter((label) => ids.includes(label.id));
}

export function trackerOf(task: Task) {
  if (!task.trackedById) {
    return undefined;
  }
  return PEOPLE.find((person) => person.id === task.trackedById);
}

export function isStatusId(value: unknown): value is StatusId {
  return STATUSES.some((status) => status.id === value);
}

export function isPriorityId(value: unknown): value is PriorityId {
  return PRIORITIES.some((priority) => priority.id === value);
}

export function isScope(value: unknown): value is Scope {
  return SCOPES.some((scope) => scope.id === value);
}

export function scopeOf(id: Scope) {
  return byId(SCOPES, id);
}

export function taskKeyOf(task: Task) {
  return `${TEAM_KEY}-${task.number}`;
}

export function isInScope(status: StatusId, scope: Scope) {
  if (scope === 'all') {
    return true;
  }
  const isDone = status === 'done';
  if (scope === 'done') {
    return isDone;
  }
  return !isDone;
}

export function matchesSearch(task: Task, query: string) {
  const needle = query.trim().toLowerCase();
  if (!needle) {
    return true;
  }
  const title = task.title.toLowerCase();
  const key = taskKeyOf(task).toLowerCase();
  return title.includes(needle) || key.includes(needle);
}

function matchesAny(selected: string[], values: string[]) {
  if (selected.length === 0) {
    return true;
  }
  return values.some((value) => selected.includes(value));
}

export function assigneeValuesOf(task: Task) {
  if (task.assigneeIds.length === 0) {
    return [NO_ASSIGNEE];
  }
  return task.assigneeIds;
}

export function matchesFilters(task: Task, filters: Filters) {
  const checks = [
    matchesAny(filters.status, [task.status]),
    matchesAny(filters.priority, [task.priority]),
    matchesAny(filters.type, [task.type]),
    matchesAny(filters.label, task.labelIds),
    matchesAny(filters.assignee, assigneeValuesOf(task)),
  ];
  return checks.every(Boolean);
}

export function activeFilterCountOf(filters: Filters) {
  let count = 0;
  for (const values of Object.values(filters)) {
    count += values.length;
  }
  return count;
}

export function isFiltering(query: string, filters: Filters) {
  const hasQuery = query.trim().length > 0;
  const hasFilters = activeFilterCountOf(filters) > 0;
  return hasQuery || hasFilters;
}

export function toggledIds<Id extends string>(
  ids: Id[],
  id: Id,
  isIncluded: boolean
): Id[] {
  const withoutId = ids.filter((current) => current !== id);
  if (isIncluded) {
    return [...withoutId, id];
  }
  return withoutId;
}

export function toggledFilters(
  filters: Filters,
  key: FilterKey,
  value: string,
  isIncluded: boolean
): Filters {
  const values = toggledIds(filters[key], value, isIncluded);
  return { ...filters, [key]: values };
}

export function scopeCountsOf(tasks: Task[]): Record<Scope, number> {
  const doneCount = tasks.filter((task) => task.status === 'done').length;
  const activeCount = tasks.length - doneCount;
  return { active: activeCount, done: doneCount, all: tasks.length };
}

export function groupsOf(
  tasks: Task[],
  scope: Scope,
  placementOf: (task: Task) => StatusId,
  draftStatus: StatusId | null
): TaskGroupData[] {
  const groups: TaskGroupData[] = [];
  for (const status of SCOPE_GROUPS[scope]) {
    const groupTasks = tasks.filter((task) => placementOf(task) === status);
    const hasTasks = groupTasks.length > 0;
    const isDrafting = draftStatus === status;
    if (hasTasks || isDrafting) {
      groups.push({ status, tasks: groupTasks });
    }
  }
  return groups;
}

export function patchedTask(
  task: Task,
  taskId: string,
  patch: Partial<Task>
): Task {
  if (task.id !== taskId) {
    return task;
  }
  return { ...task, ...patch };
}

export function nextTaskNumberOf(tasks: Task[]) {
  const numbers = tasks.map((task) => task.number);
  return Math.max(0, ...numbers) + 1;
}

export function dueLabelOf(due: string) {
  return format(parseISO(due), 'MMM d');
}

export function isOverdue(task: Task) {
  if (!task.due) {
    return false;
  }
  if (task.status === 'done') {
    return false;
  }
  return isBefore(parseISO(task.due), parseISO(TODAY));
}

export function countLabel(count: number, singular: string, plural: string) {
  if (count === 1) {
    return `${count} ${singular}`;
  }
  return `${count} ${plural}`;
}

export function peopleSentenceOf(names: string[]) {
  if (names.length === 0) {
    return 'nobody';
  }
  if (names.length === 1) {
    return names[0];
  }
  const head = names.slice(0, -1).join(', ');
  const last = names[names.length - 1];
  return `${head} and ${last}`;
}

'use client';

import { motion, useReducedMotion } from 'motion/react';

import { cn } from '@/registry/ndeko/lib/utils';

import type { PriorityId, StatusId, Task } from './data';
import { heightPresenceOf } from './motion-parts';
import { AssigneePicker, PriorityPicker, StatusPicker } from './property-menus';
import {
  IssueTypeGem,
  LabelChips,
  LivePill,
  SubTaskCountTag,
} from './task-glyphs';
import {
  DUE_CELL,
  ID_CELL,
  LABELS_CELL,
  PRIORITY_CELL,
  ROW_CLASS,
  TASK_GRID,
  TRACKED_ROW,
} from './task-grid';
import { dueLabelOf, isOverdue, taskKeyOf, trackerOf } from './task-model';

export type TaskRowHandlers = {
  onStatusChange: (taskId: string, status: StatusId) => void;
  onPriorityChange: (taskId: string, priority: PriorityId) => void;
  onAssigneesChange: (taskId: string, assigneeIds: string[]) => void;
};

type TaskRowProps = TaskRowHandlers & {
  task: Task;
};

function dueToneOf(task: Task) {
  if (isOverdue(task)) {
    return 'text-destructive-ink';
  }
  return 'text-muted-foreground';
}

function DueDate({ task }: { task: Task }) {
  if (!task.due) {
    return null;
  }
  return (
    <span className={cn('text-xs tabular-nums', dueToneOf(task))}>
      {dueLabelOf(task.due)}
      {isOverdue(task) && <span className='sr-only'>, overdue</span>}
    </span>
  );
}

export function TaskRow({
  task,
  onStatusChange,
  onPriorityChange,
  onAssigneesChange,
}: TaskRowProps) {
  const shouldReduceMotion = useReducedMotion();
  const presence = heightPresenceOf(shouldReduceMotion);
  const isDone = task.status === 'done';
  const tracker = trackerOf(task);
  const isTracked = Boolean(tracker);

  return (
    <motion.div
      role='row'
      {...presence}
      className={cn(TASK_GRID, ROW_CLASS, isTracked && TRACKED_ROW)}
    >
      <div role='cell' className={PRIORITY_CELL}>
        <PriorityPicker
          priority={task.priority}
          onChange={(priority) => onPriorityChange(task.id, priority)}
        />
      </div>
      <div
        role='cell'
        className={cn(ID_CELL, 'text-muted-foreground text-xs tabular-nums')}
      >
        {taskKeyOf(task)}
      </div>
      <div role='cell' className='flex'>
        <StatusPicker
          status={task.status}
          onChange={(status) => onStatusChange(task.id, status)}
        />
      </div>
      <div role='cell' className='flex min-w-0 items-center gap-2'>
        <IssueTypeGem type={task.type} />
        <span
          className={cn(
            'truncate text-[13px]',
            isDone && 'text-muted-foreground'
          )}
        >
          {task.title}
        </span>
        {task.subTasks && <SubTaskCountTag count={task.subTasks} />}
        {tracker && <LivePill personName={tracker.name} />}
      </div>
      <div role='cell' className={LABELS_CELL}>
        <LabelChips labelIds={task.labelIds} />
      </div>
      <div role='cell' className='flex justify-end @2xl:justify-start'>
        <AssigneePicker
          assigneeIds={task.assigneeIds}
          onChange={(assigneeIds) => onAssigneesChange(task.id, assigneeIds)}
        />
      </div>
      <div role='cell' className={DUE_CELL}>
        <DueDate task={task} />
      </div>
    </motion.div>
  );
}

'use client';

import { useReducedMotion } from 'motion/react';
import { useEffect, useRef, useState } from 'react';

import type { StatusId, Task } from './data';

const MOVE_DELAY_MS = 450;

type HeldPlacements = Record<string, StatusId>;

function withoutKey(placements: HeldPlacements, taskId: string) {
  const next = { ...placements };
  delete next[taskId];
  return next;
}

function heldOnce(
  placements: HeldPlacements,
  taskId: string,
  status: StatusId
): HeldPlacements {
  if (placements[taskId]) {
    return placements;
  }
  return { ...placements, [taskId]: status };
}

export function useDelayedPlacement() {
  const shouldReduceMotion = useReducedMotion();
  const [held, setHeld] = useState<HeldPlacements>({});
  const timers = useRef(new Map<string, ReturnType<typeof setTimeout>>());

  useEffect(() => {
    const pending = timers.current;
    return () => {
      pending.forEach((timer) => clearTimeout(timer));
    };
  }, []);

  function release(taskId: string) {
    timers.current.delete(taskId);
    setHeld((current) => withoutKey(current, taskId));
  }

  function hold(taskId: string, previousStatus: StatusId) {
    if (shouldReduceMotion) {
      return;
    }
    const existing = timers.current.get(taskId);
    if (existing) {
      clearTimeout(existing);
    }
    setHeld((current) => heldOnce(current, taskId, previousStatus));
    const timer = setTimeout(() => release(taskId), MOVE_DELAY_MS);
    timers.current.set(taskId, timer);
  }

  function placementOf(task: Task) {
    return held[task.id] ?? task.status;
  }

  return { hold, placementOf };
}

